  output := Join(parts, "");
  // Join costs (charged length of the parts) + |parts|; each part is charged
  // PART_CHARGE, so this is (PART_CHARGE + 1) * |parts|, and |parts| == i <= n.
  steps := steps + (PART_CHARGE + 1) * |parts| + 1;
}
